test('initial state', async () => {
  const h = await createHost();
  assert.deepEqual(await h.run(), { status: 'idle', task0: 'idle', task1: 'idle', retried0: false, retried1: false });
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nobody'), null);
  assert.equal((await h.workDone('worker0')).ok, false);
  assert.equal((await h.workDone('nobody')).ok, false);
  assert.equal((await h.cancel()).ok, false);
});

test('both complete', async () => {
  const h = await createHost();
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]).sort(), [['run', 'worker0', 'Assign', {}], ['run', 'worker1', 'Assign', {}]]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.deepEqual(await h.workDone('worker0'), { ok: true });
  const [r] = await h.inFlight();
  assert.deepEqual([r.from, r.to, r.action, r.data], ['worker0', 'run', 'Report', { task: 0, outcome: 'completed' }]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'completed', task1: 'assigned', retried0: false, retried1: false });
  await h.workDone('worker1');
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: false });
});

test('failure is retried once', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker0'); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'assigned', task1: 'assigned', retried0: true, retried1: false });
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  await h.workFailed('worker0'); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'running', task0: 'failed', task1: 'assigned', retried0: true, retried1: false });
  await h.workDone('worker1'); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'completed', retried0: true, retried1: false });
});

test('retried task completes', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker1'); await h.deliverAll();
  await h.workDone('worker1'); await h.workDone('worker0'); await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: true });
});

test('failure while cancelling is not retried', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker0');
  await h.cancel();
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'failed', task0: 'failed', task1: 'cancelled', retried0: false, retried1: false });
});

test('cancel', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workDone('worker0'); await h.deliverAll();
  assert.deepEqual(await h.cancel(), { ok: true });
  assert.equal((await h.cancel()).ok, false);
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.to, m.action]), [['worker1', 'Abort']]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
  assert.deepEqual(await h.run(), { status: 'cancelled', task0: 'completed', task1: 'cancelled' });
});

test('cancel races with completion', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workDone('worker0');
  await h.workDone('worker1');
  await h.cancel();
  const aborts = (await h.inFlight()).filter((m) => m.action === 'Abort');
  assert.equal(aborts.length, 2);
  for (const m of aborts) await h.deliver(m.id);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: false });
});

