import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const view = (status, task0, task1, extra = {}) => ({ status, task0, task1, retried0: false, retried1: false, processed: 0, ...extra });

test('initial state', async () => {
  const h = await createHost();
  assert.deepEqual(await h.run(), view('idle', 'idle', 'idle'));
  assert.deepEqual(await h.worker('worker0'), { status: 'idle' });
  assert.equal(await h.worker('nobody'), null);
  assert.equal((await h.workDone('worker0', 1)).ok, false);
  assert.equal((await h.workDone('nobody', 1)).ok, false);
  assert.equal((await h.cancel()).ok, false);
});

test('both complete', async () => {
  const h = await createHost();
  assert.deepEqual(await h.start(), { ok: true });
  assert.equal((await h.start()).ok, false);
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 2);
  assert.deepEqual(msgs.map((m) => [m.from, m.to, m.action, m.data]).sort(), [['run', 'worker0', 'Assign', {}], ['run', 'worker1', 'Assign', {}]]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'busy' });
  assert.equal((await h.workDone('worker0', 0)).ok, false);
  assert.equal((await h.workDone('worker0', 3)).ok, false);
  assert.deepEqual(await h.workDone('worker0', 2), { ok: true });
  const [r] = await h.inFlight();
  assert.deepEqual([r.from, r.to, r.action, r.data], ['worker0', 'run', 'Report', { task: 0, outcome: 'completed', items: 2 }]);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'completed', 'assigned', { processed: 2 }));
  await h.workDone('worker1', 1);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed', { processed: 3 }));
});

test('failure is retried once', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker0');
  const [r] = await h.inFlight();
  assert.deepEqual(r.data, { task: 0, outcome: 'failed', items: 0 });
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'assigned', 'assigned', { retried0: true }));
  assert.deepEqual(await h.worker('worker0'), { status: 'busy' });
  await h.workFailed('worker0'); await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'failed', 'assigned', { retried0: true }));
  await h.workDone('worker1', 2); await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'failed', 'completed', { retried0: true, processed: 2 }));
});

test('retried task completes', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker1'); await h.deliverAll();
  await h.workDone('worker1', 1); await h.workDone('worker0', 1); await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed', { retried1: true, processed: 2 }));
});

test('failure while cancelling is not retried', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workFailed('worker0');
  await h.cancel();
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('failed', 'failed', 'cancelled'));
});

test('timeout fails the task, aborts the worker, ignores its late report', async () => {
  const h = await createHost();
  assert.equal((await h.taskTimeout(0)).ok, false);
  await h.start(); await h.deliverAll();
  assert.equal((await h.taskTimeout(2)).ok, false);
  await h.workDone('worker0', 2);
  assert.deepEqual(await h.taskTimeout(0), { ok: true });
  assert.equal((await h.taskTimeout(0)).ok, false);
  assert.deepEqual(await h.run(), view('running', 'failed', 'assigned'));
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('running', 'failed', 'assigned'));
  assert.deepEqual(await h.taskTimeout(1), { ok: true });
  assert.deepEqual(await h.run(), view('failed', 'failed', 'failed'));
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
});

test('timeout while cancelling', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workDone('worker0', 1); await h.deliverAll();
  await h.cancel();
  assert.deepEqual(await h.taskTimeout(1), { ok: true });
  assert.deepEqual(await h.run(), view('failed', 'completed', 'failed', { processed: 1 }));
  await h.deliverAll();
  assert.equal((await h.run()).status, 'failed');
});

test('cancel', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workDone('worker0', 2); await h.deliverAll();
  assert.deepEqual(await h.cancel(), { ok: true });
  assert.equal((await h.cancel()).ok, false);
  const msgs = await h.inFlight();
  assert.deepEqual(msgs.map((m) => [m.to, m.action]), [['worker1', 'Abort']]);
  await h.deliverAll();
  assert.deepEqual(await h.worker('worker1'), { status: 'idle' });
  assert.deepEqual(await h.run(), view('cancelled', 'completed', 'cancelled', { processed: 2 }));
});

test('cancel races with completion', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workDone('worker0', 2);
  await h.workDone('worker1', 2);
  await h.cancel();
  const aborts = (await h.inFlight()).filter((m) => m.action === 'Abort');
  assert.equal(aborts.length, 2);
  for (const m of aborts) await h.deliver(m.id);
  await h.deliverAll();
  assert.deepEqual(await h.run(), view('completed', 'completed', 'completed', { processed: 4 }));
});

