test('cancel races with completion', async () => {
  const h = await createHost();
  await h.start(); await h.deliverAll();
  await h.workDone('worker0');
  await h.workDone('worker1');
  await h.cancel();
  const aborts = (await h.inFlight()).filter((m) => m.action === 'Abort');
  assert.equal(aborts.length, 2);
  for (const m of aborts) await h.deliver(m.id);
  await h.deliverAll();
  assert.deepEqual(await h.run(), { status: 'completed', task0: 'completed', task1: 'completed', retried0: false, retried1: false });
});
